def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'
    last_me, last_opp = history[-1]
    if n < 6:
        return 'C'
    opp_def_total = 0
    my_def_total = 0
    for (m, o) in history:
        if o == 'D':
            opp_def_total += 1
        if m == 'D':
            my_def_total += 1
    window = min(10, n)
    recent = history[-window:]
    opp_def_recent = sum(1 for (m, o) in recent if o == 'D')
    my_def_recent = sum(1 for (m, o) in recent if m == 'D')
    if n >= 96:
        if last_opp == 'D':
            return 'D'
        if opp_def_total * 2 < n:
            return 'D'
        return 'C'
    if opp_def_recent >= window:
        return 'D'
    if opp_def_recent >= window - 1 and window >= 5:
        if rng.random() < 0.85:
            return 'D'
        return 'C'
    if last_opp == 'D' and last_me == 'D':
        if rng.random() < 0.75:
            return 'D'
        return 'C'
    if last_opp == 'D' and last_me == 'C':
        if n >= 20 and opp_def_total * 3 < n:
            if rng.random() < 0.6:
                return 'C'
            return 'D'
        return 'D'
    if last_opp == 'C' and last_me == 'D':
        return 'C'
    if n >= 30 and opp_def_total * 4 <= n:
        if n < 90 and rng.random() < 0.02:
            return 'D'
        return 'C'
    if n >= 15 and opp_def_total * 2 < n:
        return 'C'
    if my_def_recent > opp_def_recent + 2:
        return 'C'
    return 'C'
